import fractions

def solve():
    def get_next(x, y):
        return [(x + y) / 2, 2 * x * y / (x + y)]

    def can_reach_1(m, n, max_steps=10):
        initial = {fractions.Fraction(m, n), fractions.Fraction(n, m)}
        current_level = {fractions.Fraction(m, n), fractions.Fraction(n, m)}
        all_seen = set(current_level)

        for _ in range(max_steps):
            if fractions.Fraction(1, 1) in all_seen:
                return True
            next_level = set()
            current_list = list(all_seen)
            for i in range(len(current_list)):
                for j in range(i + 1, len(current_list)):
                    x, y = current_list[i], current_list[j]
                    for val in get_next(x, y):
                        if val not in all_seen:
                            next_level.add(val)

            if not next_level:
                break
            all_seen.update(next_level)
            # We need to be careful about the growth of all_seen.
            # To make it more manageable, let's only add things that are "new" 
            # in each step. But the question says "in finitely many steps".
            # This could mean any number of steps.
            # However, if we reach 1, it must be in some number of steps.
            # Let's limit the number of elements in all_seen.
            if len(all_seen) > 1000:
                break
        return fractions.Fraction(1, 1) in all_seen

    results = []
    for m in range(1, 15):
        for n in range(1, 15):
            if m <= n and fractions.gcd(m, n) == 1:
                if can_reach_1(m, n, max_steps=5):
                    results.append((m, n))
    return results

