def can_reach_1(m, n, max_elements=2000):
    start_x = Fraction(m, n)
    start_y = Fraction(n, m)
    if start_x == 1: return True
    s = {start_x, start_y}
    elements = [start_x, start_y]
    idx = 0
    while idx < len(elements):
        if elements[idx] == 1: return True
        if len(s) > max_elements: return False
        x = elements[idx]
        for i in range(idx):
            y = elements[i]
            a = (x + y) / 2
            if a not in s:
                s.add(a)
                elements.append(a)
                if a == 1: return True
            h = (2 * x * y) / (x + y)
            if h not in s:
                s.add(h)
                elements.append(h)
                if h == 1: return True
        idx += 1
    return 1 in s

